%% Reproduce_simulated - the semi-simulated dataset of the paper, from generation to tables and figure (everything is public)
%
% The 10 simulated subjects are generated by the code (fake_EEG.m, fixed random seeds 1-10) and contaminated with the EOG and EMG
% epochs of EEGdenoiseNet, which are downloaded automatically the first time (03_simulated_data/get_eegdenoisenet.m). The methods are applied to
% the contaminated signal and scored against the clean signal. Nothing else has to be downloaded.
%
% Usage (from the repository folder):
%     Reproduce_simulated                 % quick test: 2 subjects, amplitude x1, no parallel pool (a few minutes); results in results/quick
%     quick = false; Reproduce_simulated  % the paper: 10 subjects, five artefact amplitudes (hours; use n_workers to run in parallel)
% Optional variables set before running: quick (default true), n_workers (default 0 if quick, 4 otherwise).
%
% Requirements: MATLAB with the Signal Processing, Wavelet and Statistics and Machine Learning toolboxes (Parallel Computing Toolbox only to
% run in parallel).
%
% Outputs (results/, results/quick for the quick test):
%   ALL_sim_rows.csv, SUMMARY_scale1.csv, SUMMARY_scales.csv, SUMMARY_friedman.csv   scores of every method (Simulated_groundtruth_evaluation.m)
%   TABLE_semisimulated.csv      Table II of the paper: SNR, RRMSE (time, frequency) and correlation, mean and SD over the subjects
%   TABLE_sensitivity_SNR.csv    Table III of the paper: SNR for the alternative settings of ASR, WT and EMD
%   Fig_artefact_amplitude.png   SNR as a function of the artefact amplitude (full run only; the values are quoted in the Results of the paper)
% The numbers of the paper are in the files of the same name that were produced by the authors (see results/README_results.txt).

if ~exist('quick', 'var'), quick = true; end
addpath(fileparts(fileparts(mfilename('fullpath')))); cfg_path('setup');
env_results = getenv('EEGDN_RESULTS');   % restored at the end
if quick
    n_subjects = 2; amplitudes = []; if ~exist('n_workers', 'var'), n_workers = 0; end
    setenv('EEGDN_RESULTS', fullfile(cfg_path('results'), 'quick'));
else
    n_subjects = 10; amplitudes = [0.25 0.5 2 4]; if ~exist('n_workers', 'var'), n_workers = 4; end
end
rd = cfg_path('results');
fprintf('Results in %s\n', rd);
Simulated_groundtruth_evaluation;       % generation, denoising and scoring against the clean signal; writes the csv files
sim_tables_(rd);
if ~quick, sim_amplitude_figure_(rd); end
setenv('EEGDN_RESULTS', env_results);

%% ------------------------------------------------------------------------------------------------------------------------------
function sim_tables_(rd)
% Tables II and III of the paper from the summaries of Simulated_groundtruth_evaluation.m
A = readtable(fullfile(rd, 'SUMMARY_scale1.csv')); A.Method = string(A.Method);
nchs = [4 8 16 31];
% ---- Table II: default settings, mean and SD over the subjects, on the contaminated channels
meths = ["None", "WT_repo", "ASR_k5", "EMD_2IMF", "ASR5_WT", "EMD2_WT"];
labs  = ["No denoising", "WT", "ASR (k=5)", "EMD (2 IMF)", "ASR->WT", "EMD->WT"];
rows = {};
for m = 1:numel(meths)
    for c = nchs
        s = A(A.Method == meths(m) & A.Nch == c, :);
        if isempty(s), continue; end
        rows(end+1,:) = {char(labs(m)), c, s.N(1), s.SNR_aff_mean, s.SNR_aff_sd, s.RRMSE_t_aff_mean, s.RRMSE_t_aff_sd, ...
                         s.RRMSE_f_aff_mean, s.RRMSE_f_aff_sd, s.CC_aff_mean, s.CC_aff_sd}; %#ok<AGROW>
end, end
T2 = cell2table(rows, 'VariableNames', {'Method','Nch','N','SNR_mean','SNR_sd','RRMSE_t_mean','RRMSE_t_sd','RRMSE_f_mean','RRMSE_f_sd','CC_mean','CC_sd'});
writetable(T2, fullfile(rd, 'TABLE_semisimulated.csv'));
fprintf('\nTable II: semi-simulated data scored against the clean signal (contaminated channels, mean over subjects)\n');
disp(T2(:, {'Method','Nch','N','SNR_mean','SNR_sd','RRMSE_t_mean','RRMSE_f_mean','CC_mean'}));

% ---- Table III: SNR of the alternative settings (source: S = SUMMARY_scale1.csv, V = Coiflet 4 variants of Simulated_groundtruth_evaluation)
fV = fullfile(rd, 'sim_wt_coif4_variants.csv'); V = table();
if isfile(fV), V = readtable(fV); V.Method = string(V.Method); end
spec = {'Preprocessed, no denoising','S','None'; 'ASR k=5 (default)','S','ASR_k5'; 'ASR k=10','S','ASR_k10'; 'ASR k=20','S','ASR_k20'; 'ASR k=30','S','ASR_k30'; ...
        'WT level 5','V','WT_coif4_L5'; 'WT level 7 (default)','S','WT_repo'; 'WT level 9','V','WT_coif4_L9'; ...
        'WT soft threshold','V','WT_coif4_soft'; 'WT universal threshold','V','WT_coif4_univ'; ...
        'WT bior4.4','S','WT_repo_bior44'; 'WT db4','S','WT_repo_db4'; 'WT sym4','S','WT_repo_sym4'; ...
        'Conventional denoising, hard','S','WT_den_hard'; 'Conventional denoising, soft','S','WT_den_soft'; ...
        'EMD first 2 IMF (default)','S','EMD_2IMF'; 'EMD first 3 IMF','S','EMD_3IMF'; 'EMD first 4 IMF','S','EMD_4IMF'; ...
        'EMD adaptive (1-40 Hz)','S','EMD_adapt'; 'EMD all but the first 2','S','EMD_rm2'; ...
        'ASR->WT (k=5)','S','ASR5_WT'; 'EMD->WT','S','EMD2_WT'; 'WT->EMD (2 IMF)','S','WT_EMD2'};
rows = {};
for i = 1:size(spec, 1)
    r = {spec{i,1}};
    for c = [31 16 8 4]
        mu = NaN; sd = NaN;
        if spec{i,2} == 'S'
            s = A(A.Method == spec{i,3} & A.Nch == c, :);
            if ~isempty(s), mu = s.SNR_aff_mean; sd = s.SNR_aff_sd; end
        elseif ~isempty(V)
            x = V.SNR_aff(V.Method == spec{i,3} & V.Nch == c); mu = mean(x, 'omitnan'); sd = std(x, 'omitnan');
        end
        r{end+1} = mu; r{end+1} = sd; %#ok<AGROW>
    end
    rows(end+1,:) = r; %#ok<AGROW>
end
T3 = cell2table(rows, 'VariableNames', {'Setting','SNR31','SD31','SNR16','SD16','SNR8','SD8','SNR4','SD4'});
writetable(T3, fullfile(rd, 'TABLE_sensitivity_SNR.csv'));
fprintf('\nTable III: SNR (dB) of the alternative settings, columns: 31, 16, 8, 4 channels\n');
disp(T3(:, {'Setting','SNR31','SNR16','SNR8','SNR4'}));
end

function sim_amplitude_figure_(rd)
% SNR as a function of the artefact amplitude, one panel per number of channels (values quoted in the Results of the paper)
B = readtable(fullfile(rd, 'SUMMARY_scales.csv')); B.Method = string(B.Method);
meths = ["None","WT_repo","ASR_k5","ASR_k20","EMD_2IMF","EMD_adapt","ASR5_WT","EMD2_WT"];
labs  = ["No denoising","WT","ASR k=5","ASR k=20","EMD 2 IMF","EMD adaptive","ASR->WT","EMD->WT"];
fig = figure('Visible', 'off', 'Position', [50 50 1400 330]); tiledlayout(1, 4, 'TileSpacing', 'compact', 'Padding', 'compact');
for c = [31 16 8 4]
    nexttile; hold on; grid on;
    for m = 1:numel(meths)
        s = sortrows(B(B.Method == meths(m) & B.Nch == c, :), 'Scale');
        if isempty(s), continue; end
        errorbar(s.Scale, s.SNR_aff, s.SNR_sd, '-o', 'DisplayName', char(labs(m)), 'LineWidth', 1);
    end
    set(gca, 'XScale', 'log'); xlabel('Artefact amplitude (multiplier)'); title(sprintf('%d channels', c));
    if c == 31, ylabel('SNR (dB)'); end
end
legend('Location', 'southwest', 'FontSize', 7);
exportgraphics(fig, fullfile(rd, 'Fig_artefact_amplitude.png'), 'Resolution', 200); close(fig);
end
